head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > refreshRow]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 에 CSS 클래스를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 다시 렌더링 할 Body Row 의 인덱스를 설정할 수 있어야 합니다.",
        "DataList 의 값을 다시 읽어 DOM 을 갱신합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "inputType='expression' 인 Cell 은 수식이 재계산됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:name(text) / 1:region(text) / 2:qty(number) / 3:total(expression = qty * 1000). 데이터 Row 4개(표시 Row 기준 인덱스 0~3).\n[절차] 1) (GridView 값만 수정) 클릭 -> 그리드 셀의 화면(DOM) 표시값만 임시로 변경(DataList 는 원본 그대로 -> 화면과 DataList 불일치). 2) rowIndex 선택 후 (refreshRow 실행) -> 해당 Row 를 DataList 값으로 다시 렌더링.\n[확인] refreshRow 실행 시 화면의 임시값이 사라지고 해당 Row 의 모든 셀이 DataList 원본값으로 복원되어 반환영역에 출력됨. total 셀은 expression 재계산값(#,###). 선택 안한 다른 Row 는 임시값 그대로 -> 표시 Row 기준 인덱스 검증."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "노트북",   "region": "서울", "qty": 3 },
        { "name": "모니터",   "region": "부산", "qty": 5 },
        { "name": "키보드",   "region": "대전", "qty": 7 },
        { "name": "마우스",   "region": "광주", "qty": 9 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody, index3 은 expression 컬럼)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="refreshRow 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="품목"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="지역"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="수량"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="합계(qty*1000)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="140" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : region (text)
    strTarget += '<w2:column width="120" style="" inputType="text" id="region" dataList="region"></w2:column>';
    // index 2 : qty (number)
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" id="qty" dataList="qty"></w2:column>';
    // index 3 : total (expression) - qty * 1000 산식 (display 로 다른 컬럼 참조)
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" displayFormat="#,###" id="total" expression="Number(display(\'qty\'))*1000"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [1단계] GridView 화면 값만 수정 : DataList 는 건드리지 않고 그리드 셀의 화면(DOM) 표시값만 임시로 변경한다.
//  -> DataList 와 화면이 불일치 상태가 됨. refreshRow 가 DataList 를 다시 읽어 해당 Row 화면을 복원하는지 확인용.
scwin.btn_modifyAllCells_onclick = function () {
    let cnt = dlt_bind.getRowCount();
    let colCnt = target1.getColumnCount();

    // 화면에만 표시할 임시값 : 초기값과 같은 형태(품목/지역/수량/합계)지만 다른 값
    let fakeMap = {
        "name":   ["태블릿", "프린터", "스피커", "웹캠"],
        "region": ["인천", "대구", "울산", "수원"],
        "qty":    ["11", "22", "33", "44"],
        "total":  ["11,000", "22,000", "33,000", "44,000"]
    };

    // 모든 표시 셀의 화면(td) 텍스트만 임시값으로 변경 (DataList 미반영)
    for (let r = 0; r < cnt; r++) {
        for (let c = 0; c < colCnt; c++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (!td) { continue; }
            let colID = target1.getColumnID(c);
            let val = (fakeMap[colID] && typeof fakeMap[colID][r] !== 'undefined') ? fakeMap[colID][r] : ("임시" + r);
            td.textContent = val;
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("GridView 화면 값만 수정 완료 (DataList 미반영). 모든 Row 의 화면이 초기값과 비슷한 형태의 다른 값으로 바뀌었지만 DataList 는 원본 유지 -> rowIndex 선택 후 (refreshRow 실행) 으로 해당 Row 만 복원 확인.");
}

// [2단계] refreshRow 실행 : 선택한 Row 를 DataList 값으로 다시 렌더링 -> 화면의 임시값이 사라지고 DataList 원본값으로 복원된다.
scwin.btn_refreshRow_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let colCnt = target1.getColumnCount();

    // refreshRow 호출 -> DataList 값을 다시 읽어 해당 Row 화면 복원 (expression(total) 은 수식 재계산)
    target1.refreshRow(rowIndex);

    // 복원된 해당 Row 의 모든 셀 화면 표시값 수집
    let restored = [];
    for (let c = 0; c < colCnt; c++) {
        let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + c + "']");
        restored.push(td ? td.textContent.trim() : '');
    }

    // 영향 없음 확인용 : 다른 Row(rowIndex 가 아닌 첫 Row) 의 표시값
    let otherIdx = (rowIndex === 0) ? 1 : 0;
    let other = [];
    for (let c = 0; c < colCnt; c++) {
        let td = document.querySelector("td[id*='target1_cell_" + otherIdx + "_" + c + "']");
        other.push(td ? td.textContent.trim() : '');
    }

    wf_body_bottom.getObj("scwin").setReturnValue("refreshRow(" + rowIndex + ") -> 해당 Row 가 DataList 기준으로 복원 (total 은 expression 재계산 #,###) : " + restored.join(', ') + " / 다른 Row(" + otherIdx + ") 는 영향 없이 임시값 유지 : " + other.join(', '));
}
